// Rebuild the catalogue from canonical lesson examples; do not edit generated data by hand.
const fs = require('node:fs'), vm = require('node:vm');
const context = { window: {} }; vm.createContext(context);
for (const file of ['course-data.js', 'assignments-data.js', 'assignment-solutions.js']) vm.runInContext(fs.readFileSync(file, 'utf8'), context);
const W = context.window, D = W.COURSE_DATA;
const ds = JSON.parse(fs.readFileSync('datastrukturer.html','utf8').match(/const DATA=(\{[^\n]+\});/)[1]);
const outputs = JSON.parse(fs.readFileSync('tests/fixtures/assignment-outputs.json','utf8'));
Object.assign(outputs, JSON.parse(fs.readFileSync('tests/fixtures/course-lab-extra-outputs.json','utf8')));
const extra = {}, titles = {}, descriptions = {};
const dsIds = ['ds-array','ds-linked-list','ds-stack','ds-queue','ds-tree','ds-graph','ds-hash'];
for (const lang of Object.keys(D.locales)) {
  titles[lang] = Object.fromEntries(D.topics.map((id,i)=>[id,D.translations[lang].topics[i][0]]));
  descriptions[lang] = Object.fromEntries(dsIds.map((id,i)=>[id,ds.lessons[lang][i].intro + ' ' + ds.lessons[lang][i].idea]));
  dsIds.forEach((id,i)=>{titles[lang][id]=ds.lessons[lang][i].title;});
  titles[lang].escapes=D.translations[lang].ui.escapes; titles[lang].formats=D.translations[lang].ui.formats;
}
for (const [i,id] of dsIds.entries()) {
  extra[id] = {};
  for (const code of Object.keys(D.programs)) extra[id][code] = code==='python'?ds.lessons.en[i].code:code==='c'?ds.c.en[i]:ds.extraCode[code][i];
}
extra.escapes = Object.fromEntries(Object.keys(D.programs).map(code=>[code,W.LANGUAGE_EXAMPLES[code].format0.code]));
extra.formats = W.LESSON_ASSIGNMENT_SOLUTIONS.formatting;
outputs.escapes = Object.fromEntries(Object.keys(D.programs).map(code=>[code,W.LANGUAGE_EXAMPLES[code].format0.output]));
outputs.formats = outputs.formatting;
const data={titles,descriptions,extra,outputs,ids:[...Object.keys(W.LESSON_ASSIGNMENTS),...dsIds,'escapes','formats'],stdin:Object.fromEntries(Object.entries(W.LESSON_ASSIGNMENTS).filter(([,v])=>v.stdin).map(([id,v])=>[id,v.stdin]))};
fs.writeFileSync('course-labs-content.js',"'use strict';\n// Generated by scripts/build-course-lab-content.cjs from course sources and native output fixtures.\n(function(root){ const data = "+JSON.stringify(data,null,2)+"; if(typeof module === 'object' && module.exports) module.exports=data; else root.CourseLabContent=data; })(typeof window==='undefined'?globalThis:window);\n");
